package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class FractionDecimalDivisionTest {
 private static Question rounded(String n,String d){return new Question(FractionToDecimalCheck.ID,FractionDecimalDivision.prompt(n,d),"poison","999");}
 private static Question plain(String n,String d){return new Question(FractionToDecimalCheck.ID,n+"/"+d+"의 값을 소수로 나타내세요.","poison","999");}
 @Test public void publicExplicitPrecisionRoundsExactDivisionWithCarryAndNoImplicitRounding(){
  String[][] cases={{"1","3","0.333"},{"1","6","0.167"},{"2","3","0.667"},{"1999","2000","1.0"},{"8","3","2.667"},{"0","3","0.0"},{"5","8","0.625"}};Checker checker=new Checker();
  for(String[] c:cases){Question q=rounded(c[0],c[1]);var g=FractionDecimalDivision.read(q);assertNotNull(g);assertTrue(g.rounded());assertEquals(FractionDecimalDivision.decimalInput(c[2]),g.value());assertTrue(checker.check(q,List.of(),List.of(c[2])).correct());assertTrue(checker.check(q,List.of(),List.of(c[2]+"0")).correct());assertFalse(checker.check(q,List.of(),List.of(c[0]+"/"+c[1])).correct());assertFalse(checker.check(q,List.of(),List.of("999.0")).correct());}
  assertNull(FractionDecimalDivision.read(plain("1","3")));assertFalse(checker.check(plain("1","3"),List.of(),List.of("0.333")).correct());assertEquals(Rational.of(1,3),FractionDecimalDivision.read(rounded("1","3")).exact());
 }
 @Test public void allTwentyThreeFramesAreBlankAndExactAndIgnoreStoredKeysWithoutMutatingQuestion(){
  Question q=rounded("01","06");q.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide stored=q.studyGuide;String prompt=q.prompt;var g=FractionDecimalDivision.read(q);assertEquals("01",g.rawNumerator());assertEquals("06",g.rawDenominator());
  HelpPlan h=HelpPlan.forQuestion(q);StudyGuide expected=FractionDecimalDivision.guide(q);assertEquals(23,h.size());assertFalse(h.canTransfer());HelpPlan.Draft draft=h.restore(null,q.id);assertEquals(FractionDecimalDivision.VERSION,draft.teachingVersion);List<String> entries=new ArrayList<>();
  for(int i=0;i<h.size();i++){assertEquals("",h.step(i).after);assertFalse(h.step(i).accepts(""));String value=expected.frames.get(i).expected;if(i==22&&!value.contains("."))value+=".0";assertTrue("stage"+i,h.step(i).accepts(value));entries.add(value);}
  assertEquals(Set.of("zero","repeat","continue"),h.step(20).options.keySet());assertTrue(h.step(20).accepts("repeat"));assertFalse(h.step(20).accepts("zero"));assertTrue(h.step(21).accepts("up"));assertFalse(h.step(21).accepts("keep"));assertFalse(h.step(22).accepts("1/6"));
  BigInteger remainder=g.initialRemainder();for(var col:g.columns()){assertEquals(remainder.multiply(BigInteger.TEN),col.current());assertEquals(col.current().divide(g.denominator()).intValueExact(),col.digit());assertEquals(g.denominator().multiply(BigInteger.valueOf(col.digit())),col.product());assertEquals(col.current().subtract(col.product()),col.remainder());remainder=col.remainder();}
  draft.stage=23;draft.entries=entries;HelpPlan.Draft restored=h.restore(draft.copy(),q.id);assertEquals(23,restored.stage);assertEquals(entries,restored.entries.subList(0,23));assertEquals("",restored.entries.get(23));assertEquals("0.167",h.enteredAnswer(draft));assertSame(stored,q.studyGuide);assertEquals(prompt,q.prompt);assertEquals("poison",q.expression);assertArrayEquals(new String[]{"999"},q.answers);
  assertEquals("zero",FractionDecimalDivision.read(rounded("5","8")).divisionState());assertEquals("continue",FractionDecimalDivision.read(rounded("1","7")).divisionState());assertFalse(FractionDecimalDivision.read(rounded("1","7")).terminating());
 }
 @Test public void referencesContainOnlyCheckedLearnerEntriesAndRelevantOperands(){
  Question q=rounded("1","6");StudyGuide guide=FractionDecimalDivision.guide(q);List<String> entries=new ArrayList<>();for(var frame:guide.frames)entries.add(frame.expected);
  assertEquals(Map.of(),FractionDecimalDivision.references(q,4,List.of()));entries.set(3,"999");assertEquals(Map.of(),FractionDecimalDivision.references(q,4,entries));entries.set(3,"1");assertEquals(Map.of("입력한 이전 나머지 r0 = ","1"),FractionDecimalDivision.references(q,4,entries));
  assertEquals(2,FractionDecimalDivision.references(q,7,entries).size());assertEquals(5,FractionDecimalDivision.references(q,20,entries).size());Map<String,String> rounding=FractionDecimalDivision.references(q,21,entries);assertEquals("0.1666",rounding.get("입력한 소수(반올림 전) = "));assertFalse(rounding.containsValue("0.167"));assertEquals(2,rounding.size());entries.set(9,"wrong");assertFalse(FractionDecimalDivision.references(q,22,entries).containsKey("입력한 소수(반올림 전) = "));
 }
 @Test public void exactLegacyShapeVersionsAndUnreducedLargeFractionHelpersRemainCompatible(){
  for(String[] c:List.of(new String[]{"3","10","4","decimal-fraction-unit-relations-v2"},new String[]{"3","6","3","fraction-as-division-decimal-v1"},new String[]{"6","12","3","fraction-as-division-decimal-v1"},new String[]{"0","3","3","fraction-as-division-decimal-v1"},new String[]{"99999999999999999999","2","3","fraction-as-division-decimal-v1"})){
   Question q=plain(c[0],c[1]);DecimalFractionRelations.attach(q);HelpPlan h=HelpPlan.forQuestion(q);assertEquals(Integer.parseInt(c[2]),h.size());assertFalse(h.canTransfer());HelpPlan.Draft old=new HelpPlan.Draft();old.questionId=q.id;old.teachingVersion=c[3];old.entries=new ArrayList<>(List.of(c[0],c[1]));old.stage=2;HelpPlan.Draft restored=h.restore(old,q.id);assertEquals(c[3],restored.teachingVersion);assertEquals(2,restored.stage);assertTrue(h.step(0).accepts(c[0]+".0"));String result=FractionDecimalDivision.read(q).value().decimalText();if(!result.contains("."))result+=".0";assertTrue(new Checker().check(q,List.of(),List.of(result)).correct());assertTrue(h.step(h.size()-1).accepts(result));assertFalse(h.step(h.size()-1).accepts(c[0]+"/"+c[1]));
  }
  Question q=plain("1","73786976294838206464");var g=FractionDecimalDivision.read(q);assertNotNull(g);String value=g.value().decimalText();assertTrue(value.substring(value.indexOf('.')+1).length()>12);assertTrue(new Checker().check(q,List.of(),List.of(value)).correct());assertTrue(HelpPlan.forQuestion(q).step(2).accepts(value));try{Expression.number(value);fail("Other expression decimal guard was widened");}catch(IllegalArgumentException expected){}
 }
 @Test public void publicAndNumericGuardsRejectBadFormsAndInvalidPublicNeverUsesStoredGuide(){
  for(Question q:List.of(rounded("1","0"),rounded("-1","6"),rounded("1".repeat(21),"6"),rounded("1","1".repeat(21)),rounded("1e2","6"),plain("1","7"))){q.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide saved=q.studyGuide;assertNull(FractionDecimalDivision.read(q));assertNull(HelpPlan.forQuestion(q));assertSame(saved,q.studyGuide);assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("999.0")).status);}
  Question trailing=rounded("1","6");trailing.prompt+=" trailing";assertNull(FractionDecimalDivision.read(trailing));assertNull(FractionDecimalDivision.read(null));assertNull(FractionDecimalDivision.guide(null));
  for(String input:List.of("0."+"0".repeat(119),BigInteger.ONE.shiftLeft(512)+".0","1/3","1e-3","1+1","((0.333))","0,333","1",".333","0.333."))assertNull(input,FractionDecimalDivision.decimalInput(input));assertEquals(Rational.of(333,1000),FractionDecimalDivision.decimalInput("+0.3330"));assertEquals(Rational.of(-1,2),FractionDecimalDivision.decimalInput("−0.50"));
  Question other=new Question("fracMul","(1/2) × (1/2)","(1/2)*(1/2)","1/4");assertFalse(HelpPlan.forQuestion(other).step(0).accepts("0".repeat(31)+"1"));
 }
}
